// Validate incoming payload
const input = $input.first().json;

const required = ['opportunity_id', 'transcript'];
const missing = required.filter(f => !input[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Build context for LLM
const context = {
  opportunity_id: input.opportunity_id,
  opportunity_name: input.opportunity_name || 'Unknown',
  account_tier: input.account_tier || 'T2',
  current_stage: input.current_stage || 'S1_Discovery',
  ae_name: input.ae_name || 'Unknown',
  previous_scores: input.previous_scores || { M: 0, E: 0, DC: 0, DP: 0, I: 0, C_champ: 0, C_comp: 0 },
  transcript: input.transcript,
  timestamp: new Date().toISOString()
};

return [{ json: context }];

