// Parse LLM response and prepare CRM update + notification
const input = $('Validate & Prepare').first().json;
const llmResponse = $input.first().json;

// Parse the JSON from LLM response
let extraction;
try {
  // Handle case where response is already parsed or is a string
  if (typeof llmResponse.message === 'string') {
    // Remove any markdown code fences if present
    let cleaned = llmResponse.message.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    extraction = JSON.parse(cleaned);
  } else if (llmResponse.message?.content) {
    let cleaned = llmResponse.message.content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    extraction = JSON.parse(cleaned);
  } else {
    extraction = llmResponse;
  }
} catch (e) {
  throw new Error(`Failed to parse LLM response: ${e.message}`);
}

// Calculate composite score if not present
const scores = extraction.meddicc_assessment;
if (!extraction.composite_score || !extraction.composite_score.value) {
  const m = scores.metrics.score;
  const e = scores.economic_buyer.score;
  const dc = scores.decision_criteria.score;
  const dp = scores.decision_process.score;
  const i = scores.identify_pain.score;
  const c = scores.champion.score;
  const comp = scores.competition.score;

  const composite = (m*0.15 + e*0.20 + dc*0.10 + dp*0.10 + i*0.20 + c*0.20 + comp*0.05) * 100 / 3;
  extraction.composite_score = {
    value: Math.round(composite * 100) / 100,
    interpretation: composite >= 80 ? 'STRONG' : composite >= 60 ? 'DEVELOPING' : composite >= 40 ? 'WEAK' : 'CRITICAL'
  };
}

// Build Slack notification
const prevScores = input.previous_scores;
const scoreEmoji = (curr, prev) => curr > prev ? '⬆️' : curr < prev ? '⬇️' : '➡️';

const slackMessage = {
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `📞 Post-Call MEDDICC Update: ${input.opportunity_name}` }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*AE:* ${input.ae_name}` },
        { type: 'mrkdwn', text: `*Tier:* ${input.account_tier}` },
        { type: 'mrkdwn', text: `*Stage:* ${input.current_stage}` },
        { type: 'mrkdwn', text: `*Composite:* ${extraction.composite_score.value} (${extraction.composite_score.interpretation})` }
      ]
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*MEDDICC Scores:*\n` +
          `M: ${scores.metrics.score}/3 ${scoreEmoji(scores.metrics.score, prevScores.M)} | ` +
          `E: ${scores.economic_buyer.score}/3 ${scoreEmoji(scores.economic_buyer.score, prevScores.E)} | ` +
          `DC: ${scores.decision_criteria.score}/3 ${scoreEmoji(scores.decision_criteria.score, prevScores.DC)} | ` +
          `DP: ${scores.decision_process.score}/3 ${scoreEmoji(scores.decision_process.score, prevScores.DP)} | ` +
          `I: ${scores.identify_pain.score}/3 ${scoreEmoji(scores.identify_pain.score, prevScores.I)} | ` +
          `C: ${scores.champion.score}/3 ${scoreEmoji(scores.champion.score, prevScores.C_champ)} | ` +
          `Comp: ${scores.competition.score}/3 ${scoreEmoji(scores.competition.score, prevScores.C_comp)}`
      }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*요약:* ${extraction.summary_ko || 'N/A'}` }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Next Best Action:* ${extraction.next_best_actions?.[0]?.action || 'N/A'}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: extraction.stage_gate?.next_stage_eligible
          ? '✅ *Stage Gate:* 다음 단계 진입 조건 충족'
          : `⚠️ *Stage Gate:* 다음 단계 미충족 — ${(extraction.stage_gate?.blocking_elements || []).map(b => `${b.element}(${b.actual}/${b.required})`).join(', ')}`
      }
    },
    {
      type: 'actions',
      elements: [
        { type: 'button', text: { type: 'plain_text', text: '✅ Approve CRM Update' }, style: 'primary', action_id: 'approve_crm', value: input.opportunity_id },
        { type: 'button', text: { type: 'plain_text', text: '✏️ Edit Before Saving' }, action_id: 'edit_crm', value: input.opportunity_id },
        { type: 'button', text: { type: 'plain_text', text: '❌ Reject' }, style: 'danger', action_id: 'reject_crm', value: input.opportunity_id }
      ]
    }
  ]
};

return [{
  json: {
    ...input,
    extraction,
    crm_updates: extraction.crm_updates,
    slack_message: slackMessage,
    db_record: {
      opportunity_id: input.opportunity_id,
      opportunity_name: input.opportunity_name,
      account_tier: input.account_tier,
      current_stage: input.current_stage,
      m_score: scores.metrics.score,
      e_score: scores.economic_buyer.score,
      dc_score: scores.decision_criteria.score,
      dp_score: scores.decision_process.score,
      i_score: scores.identify_pain.score,
      c_champ_score: scores.champion.score,
      c_comp_score: scores.competition.score,
      composite_score: extraction.composite_score.value,
      extraction_result: extraction,
      stage_gate_passed: extraction.stage_gate?.next_stage_eligible || false,
      blocking_elements: extraction.stage_gate?.blocking_elements || []
    }
  }
}];
